// Analisa status dos serviços
const items = $input.all();
const services = {
  whatsapp: {
    status: 'unknown',
    message: '',
    error: null
  },
  database: {
    status: 'unknown',
    message: '',
    error: null
  },
  email: {
    status: 'unknown',
    message: '',
    error: null
  }
};

// WhatsApp Status
const whatsappData = items[0]?.json;
if (whatsappData?.instance?.state === 'open') {
  services.whatsapp.status = 'healthy';
  services.whatsapp.message = 'WhatsApp conectado e operacional';
} else if (whatsappData?.error) {
  services.whatsapp.status = 'error';
  services.whatsapp.message = 'Erro ao conectar com WhatsApp';
  services.whatsapp.error = whatsappData.error.message || 'Erro desconhecido';
} else {
  services.whatsapp.status = 'warning';
  services.whatsapp.message = 'WhatsApp desconectado ou em estado inválido';
}

// Database Status
const dbData = items[1]?.json;
if (dbData?.postgres_version) {
  services.database.status = 'healthy';
  services.database.message = `PostgreSQL operacional - ${dbData.database_name}`;
  services.database.details = {
    version: dbData.postgres_version,
    size: (parseInt(dbData.database_size) / 1024 / 1024).toFixed(2) + ' MB'
  };
} else if (dbData?.error) {
  services.database.status = 'error';
  services.database.message = 'Erro ao conectar com banco de dados';
  services.database.error = dbData.error.message || 'Erro desconhecido';
} else {
  services.database.status = 'warning';
  services.database.message = 'Status do banco desconhecido';
}

// Email Status
const emailData = items[2]?.json;
if (emailData && !emailData.error) {
  services.email.status = 'healthy';
  services.email.message = 'Conexão IMAP operacional';
} else if (emailData?.error) {
  services.email.status = 'error';
  services.email.message = 'Erro ao conectar com servidor de email';
  services.email.error = emailData.error.message || 'Erro desconhecido';
} else {
  services.email.status = 'warning';
  services.email.message = 'Status do email desconhecido';
}

// Status geral
const hasError = Object.values(services).some(s => s.status === 'error');
const hasWarning = Object.values(services).some(s => s.status === 'warning');

const overallStatus = hasError ? 'error' : hasWarning ? 'warning' : 'healthy';
const timestamp = new Date().toISOString();

return {
  timestamp: timestamp,
  overallStatus: overallStatus,
  services: services,
  requiresAlert: hasError || hasWarning
};

// Analisa filas e pedidos pendentes
const data = $input.first().json;
const alerts = [];

// Pedidos travados
if (data.total_stuck > 0) {
  const stuckOrders = Array.isArray(data.stuck_orders) ? data.stuck_orders : [];
  alerts.push({
    type: 'stuck_orders',
    severity: 'high',
    title: '🚨 Pedidos Travados',
    message: `${data.total_stuck} pedido(s) estão parados há muito tempo`,
    details: stuckOrders.map(o => ({
      orderId: o.order_id,
      client: o.client_name,
      status: o.status,
      waitingTime: Math.round(o.minutes_waiting) + ' minutos'
    }))
  });
}

// Pedidos expirando
if (data.total_expiring > 0) {
  const expiringOrders = Array.isArray(data.expiring_orders) ? data.expiring_orders : [];
  alerts.push({
    type: 'expiring_orders',
    severity: 'medium',
    title: '⏰ Orçamentos Expirando',
    message: `${data.total_expiring} orçamento(s) expirarão em breve`,
    details: expiringOrders.map(o => ({
      orderId: o.order_id,
      client: o.client_name,
      value: 'R$ ' + parseFloat(o.total_amount || 0).toFixed(2),
      expiresIn: Math.round(o.minutes_remaining) + ' minutos'
    }))
  });
}

// Fila alta
if (data.total_pending > 10) {
  alerts.push({
    type: 'high_queue',
    severity: 'low',
    title: '📊 Fila Alta',
    message: `${data.total_pending} pedidos pendentes no sistema`,
    details: null
  });
}

return {
  timestamp: new Date().toISOString(),
  hasAlerts: alerts.length > 0,
  alertCount: alerts.length,
  alerts: alerts,
  metrics: {
    totalPending: data.total_pending,
    totalStuck: data.total_stuck,
    totalExpiring: data.total_expiring
  }
};

// Formata alertas para Slack
const data = $input.first().json;
const alerts = data.alerts || [];

const attachments = alerts.map(alert => {
  const color = alert.severity === 'high' ? '#dc3545' : 
                alert.severity === 'medium' ? '#ffc107' : '#17a2b8';

  let text = alert.message;

  if (alert.details && alert.details.length > 0) {
    if (alert.type === 'stuck_orders') {
      text += '\n\n*Pedidos:*\n';
      text += alert.details.map(d => 
        `• \`${d.orderId}\` - ${d.client} (${d.status}) - ${d.waitingTime}`
      ).join('\n');
    } else if (alert.type === 'expiring_orders') {
      text += '\n\n*Orçamentos:*\n';
      text += alert.details.map(d => 
        `• \`${d.orderId}\` - ${d.client} - ${d.value} - Expira em ${d.expiresIn}`
      ).join('\n');
    }
  }

  return {
    color: color,
    title: alert.title,
    text: text,
    footer: 'Sistema de Monitoramento',
    ts: Date.now() / 1000
  };
});

const mainText = data.alertCount === 1 
  ? ':warning: *1 Alerta Detectado*'
  : `:warning: *${data.alertCount} Alertas Detectados*`;

return {
  mainText: mainText,
  attachments: attachments
};

// Tenta reconectar WhatsApp se desconectado
const status = $json.services?.whatsapp?.status;

if (status === 'error' || status === 'warning') {
  return {
    shouldReconnect: true,
    reason: 'WhatsApp desconectado ou com erro'
  };
}

return {
  shouldReconnect: false,
  reason: 'WhatsApp já está conectado'
};
